  const purchases=deliveredPurchases().sort((a,b)=>b.order.date.localeCompare(a.order.date));
  const filter=params.get('status')||'all';
  const filtered=purchases.filter(purchase=>{const status=reviewStatus(purchase);return filter==='all'||(filter==='needs'&&['not-reviewed','draft','deleted'].includes(status))||(filter==='reviewed'&&['submitted','edited'].includes(status));});
  const count=purchases.length,needs=purchases.filter(purchase=>['not-reviewed','draft','deleted'].includes(reviewStatus(purchase))).length;
