document.addEventListener('input',e=>{
  if(e.target.id!=='review-text'&&e.target.id!=='review-title')return;
  const params=new URLSearchParams(location.search),key=reviewId(params.get('order'),params.get('product')),reviews=readReviews(),record=reviews[key];if(!record)return;
  if(e.target.id==='review-text'){record.text=e.target.value;record.errors=(record.errors||[]).filter(error=>error!=='text');const error=document.querySelector('.review-text-foot .review-validation');if(error)error.hidden=true;e.target.setAttribute('aria-invalid','false');const counter=document.querySelector('#review-character-count');if(counter)counter.textContent=String(e.target.value.length);}
  else record.title=e.target.value;
  writeReviews(reviews);
});
document.addEventListener('submit',e=>{
  if(e.target.id!=='review-form')return;
  e.preventDefault();const params=new URLSearchParams(location.search),key=reviewId(params.get('order'),params.get('product')),reviews=readReviews(),record=reviews[key];if(!record)return;
  record.title=document.querySelector('#review-title')?.value.trim()||'';record.text=document.querySelector('#review-text')?.value.trim()||'';record.errors=[];
  if(!record.rating)record.errors.push('rating');if(record.text.length<REVIEW_MIN||record.text.length>REVIEW_MAX)record.errors.push('text');
  if(record.errors.length){writeReviews(reviews);document.querySelector('.review-rating-input')?.setAttribute('aria-invalid',String(record.errors.includes('rating')));const ratingError=document.querySelector('.review-rating-field .review-validation');if(ratingError)ratingError.hidden=!record.errors.includes('rating');const textError=document.querySelector('.review-text-foot .review-validation');if(textError)textError.hidden=!record.errors.includes('text');document.querySelector('#review-text')?.setAttribute('aria-invalid',String(record.errors.includes('text')));return;}
  record.status=record.status==='submitted'||record.status==='edited'?'edited':'submitted';record.editing=false;record.errors=[];record.updatedAt=new Date().toISOString();writeReviews(reviews);location.href=`/reviews?product=${encodeURIComponent(record.productId)}&order=${encodeURIComponent(record.orderId)}&view=1&saved=1`;
});
document.addEventListener('keydown',e=>{
  const star=e.target.closest('[data-review-rating]');if(!star||!['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(e.key))return;
  e.preventDefault();const current=Number(star.dataset.reviewRating);const next=e.key==='Home'?1:e.key==='End'?5:Math.min(5,Math.max(1,current+(['ArrowRight','ArrowUp'].includes(e.key)?1:-1)));
  const target=document.querySelector(`[data-review-rating="${next}"]`);target?.click();target?.focus();
});

document.addEventListener('click',e=>{
  const action=e.target.closest('[data-seller-product-action]');if(action){const kind=action.dataset.sellerProductAction;
    if(kind==='add'){openSellerProductModal('add',null,action);return;}
    if(kind==='edit'){openSellerProductModal('edit',action.dataset.id,action);return;}
    if(kind==='close-modal'){closeSellerProductModal();return;}
    if(kind==='archive'){sellerProductUI.confirm=action.dataset.id;sellerProductReturnFocus=action;renderSellerProductModal();document.querySelector('[data-seller-product-action="cancel-archive"]')?.focus();return;}
    if(kind==='cancel-archive'){sellerProductUI.confirm=null;renderSellerProductModal();sellerProductReturnFocus?.focus?.();return;}
    if(kind==='confirm-archive'){const rows=readSellerManagedProducts(),product=rows.find(row=>row.id===action.dataset.id);if(product){product.status='Archived';product.updatedAt=sellerToday();writeSellerManagedProducts(rows);syncSellerMarketplaceCatalog();sellerProductUI.confirm=null;refreshSellerProductPage();notify(t('Product archived'));}return;}
    if(kind==='restore'){const rows=readSellerManagedProducts(),product=rows.find(row=>row.id===action.dataset.id);if(product){product.status='Active';product.updatedAt=sellerToday();writeSellerManagedProducts(rows);syncSellerMarketplaceCatalog();refreshSellerProductPage();notify(t('Product restored'));}return;}
    if(kind==='reset'){resetSellerProductFilters();return;}
  }
  const page=e.target.closest('[data-seller-product-page]');if(page&&!page.disabled){sellerProductUI.page=Number(page.dataset.sellerProductPage);refreshSellerProductResults();document.querySelector('.seller-product-manager')?.scrollIntoView({behavior:'smooth',block:'start'});}
});
document.addEventListener('input',e=>{if(e.target.id!=='seller-product-search')return;sellerProductUI.query=e.target.value.trim();sellerProductUI.page=1;refreshSellerProductResults();});
document.addEventListener('change',e=>{
  if(e.target.id==='seller-category-filter')sellerProductUI.category=e.target.value;
  else if(e.target.id==='seller-status-filter')sellerProductUI.status=e.target.value;
  else if(e.target.id==='seller-stock-filter')sellerProductUI.stock=e.target.value;
  else if(e.target.id==='seller-products-sort')sellerProductUI.sort=e.target.value;
  else return;sellerProductUI.page=1;refreshSellerProductResults();
});
document.addEventListener('input',e=>{if(!e.target.closest('#seller-product-form'))return;if(e.target.checkValidity())e.target.removeAttribute('aria-invalid');if(sellerProductUI.error){sellerProductUI.error='';const node=document.querySelector('#seller-product-form-error');if(node){node.textContent='';node.hidden=true;}}});
document.addEventListener('change',e=>{if(!e.target.closest('#seller-product-form'))return;if(e.target.checkValidity())e.target.removeAttribute('aria-invalid');if(sellerProductUI.error){sellerProductUI.error='';const node=document.querySelector('#seller-product-form-error');if(node){node.textContent='';node.hidden=true;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='seller-product-form')return;e.preventDefault();saveSellerProductForm(e.target);});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&(sellerProductUI.modal||sellerProductUI.confirm)){closeSellerProductModal();return;}
  const dialog=document.querySelector('.seller-product-modal[role="dialog"]');if(e.key!=='Tab'||!dialog)return;const focusable=[...dialog.querySelectorAll('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled])')];if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
});
